components.css:
.ds-btn-primary {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  height: 32px;
  padding: 0 13px;
  border: 1px solid #e29524;
  border-radius: 4px;
  background: #e29524;
  color: #170f00;
  font: 700 13px/1.3 system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  white-space: nowrap;
  cursor: pointer;
  transition: background 140ms cubic-bezier(0.16, 1, 0.3, 1), border-color 140ms cubic-bezier(0.16, 1, 0.3, 1);
}
.ds-btn-primary:hover {
  background: #eba336;
  border-color: #eba336;
}
.ds-btn-primary:focus-visible {
  outline: 2px solid #46a0e6;
  outline-offset: 2px;
}
.ds-btn-primary:disabled {
  opacity: 0.48;
  cursor: default;
}
.ds-btn-ico {
  width: 15px;
  height: 15px;
  flex: none;
}

.ds-btn-secondary {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  height: 32px;
  padding: 0 13px;
  border: 1px solid #4c6282;
  border-radius: 4px;
  background: #121822;
  color: #eef2f7;
  font: 600 13px/1.3 system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  white-space: nowrap;
  cursor: pointer;
  transition: background 140ms cubic-bezier(0.16, 1, 0.3, 1), border-color 140ms cubic-bezier(0.16, 1, 0.3, 1);
}
.ds-btn-secondary:hover {
  background: #1b2434;
  border-color: #8395ae;
}
.ds-btn-secondary:focus-visible {
  outline: 2px solid #46a0e6;
  outline-offset: 2px;
}
.ds-btn-ico {
  width: 15px;
  height: 15px;
  flex: none;
}

.ds-btn-danger {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  height: 32px;
  padding: 0 13px;
  border: 1px solid #c93830;
  border-radius: 4px;
  background: #c93830;
  color: #ffffff;
  font: 700 13px/1.3 system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  white-space: nowrap;
  cursor: pointer;
  transition: background 140ms cubic-bezier(0.16, 1, 0.3, 1), border-color 140ms cubic-bezier(0.16, 1, 0.3, 1);
}
.ds-btn-danger:hover {
  background: #b52f28;
  border-color: #b52f28;
}
.ds-btn-danger:focus-visible {
  outline: 2px solid #46a0e6;
  outline-offset: 2px;
}
.ds-btn-ico {
  width: 15px;
  height: 15px;
  flex: none;
}

.ds-pill-row {
  display: inline-flex;
  flex-wrap: wrap;
  gap: 8px;
}
.ds-pill {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 2px 8px;
  border-radius: 3px;
  border: 1px solid transparent;
  font: 700 11px/1.4 ui-monospace, "SF Mono", "Cascadia Mono", Menlo, Consolas, monospace;
  letter-spacing: 0.02em;
  text-transform: uppercase;
  white-space: nowrap;
  transition: filter 140ms cubic-bezier(0.16, 1, 0.3, 1);
}
.ds-pill:hover {
  filter: brightness(1.12);
}
.ds-pill:focus-visible {
  outline: 2px solid #46a0e6;
  outline-offset: 2px;
}
.ds-pill-ico {
  width: 13px;
  height: 13px;
  flex: none;
}
.ds-pill-gate { background: #1d170c; color: #f5bd63; border-color: #5e4419; }
.ds-pill-ready { background: #0f1d16; color: #6ee0a8; border-color: #224f3a; }
.ds-pill-review { background: #0f1e2e; color: #7cc4fa; border-color: #244a6e; }
.ds-pill-blocked { background: #241214; color: #ff948d; border-color: #6b2929; }

.ds-search {
  position: relative;
  width: 220px;
  max-width: 100%;
}
.ds-search-ico {
  position: absolute;
  left: 10px;
  top: 50%;
  transform: translateY(-50%);
  width: 15px;
  height: 15px;
  color: #8395ae;
  pointer-events: none;
}
.ds-search-input {
  width: 100%;
  height: 30px;
  padding: 0 28px 0 32px;
  border: 1px solid #4c6282;
  border-radius: 4px;
  background: #121822;
  color: #eef2f7;
  caret-color: #e29524;
  font: 400 12.5px/1.4 system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  transition: border-color 140ms cubic-bezier(0.16, 1, 0.3, 1), background 140ms cubic-bezier(0.16, 1, 0.3, 1);
}
.ds-search-input::placeholder {
  color: #8395ae;
}
.ds-search-input:hover {
  border-color: #8395ae;
}
.ds-search-input:focus-visible {
  outline: 2px solid #46a0e6;
  outline-offset: 2px;
}
.ds-search-clear {
  position: absolute;
  right: 4px;
  top: 50%;
  transform: translateY(-50%);
  width: 22px;
  height: 22px;
  border: 0;
  border-radius: 3px;
  background: transparent;
  color: #8395ae;
  display: grid;
  place-items: center;
  cursor: pointer;
}
.ds-search-clear:hover {
  color: #eef2f7;
  background: #1b2434;
}
.ds-search-clear:focus-visible {
  outline: 2px solid #46a0e6;
  outline-offset: 1px;
}

.ds-route-wrap {
  padding: 10px 12px 9px;
  border-radius: 4px;
  background: #161e2b;
  border: 1px solid #233044;
  display: grid;
  gap: 8px;
  font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
}
.ds-route-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  font-size: 12px;
  color: #a3b3c9;
}
.ds-route-title {
  display: inline-flex;
  align-items: center;
  gap: 6px;
}
.ds-route-ico {
  width: 13px;
  height: 13px;
  flex: none;
  color: #8395ae;
}
.ds-route-head strong {
  color: #eef2f7;
  font-weight: 700;
}
.ds-route-pct {
  font-family: ui-monospace, "SF Mono", "Cascadia Mono", Menlo, Consolas, monospace;
  font-variant-numeric: tabular-nums;
}
.ds-route-track {
  display: flex;
  align-items: flex-start;
  width: 100%;
  padding: 4px 0 2px;
}
.ds-station {
  position: relative;
  flex: 1 1 0;
  min-width: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 5px;
  padding: 2px 2px 4px;
  border: 0;
  border-radius: 3px;
  background: transparent;
  color: inherit;
  cursor: pointer;
  transition: background 140ms cubic-bezier(0.16, 1, 0.3, 1);
}
.ds-station:not(:first-child)::before,
.ds-station:not(:last-child)::after {
  content: "";
  position: absolute;
  top: 9px;
  height: 2px;
  z-index: 1;
  background: #2c3b52;
}
.ds-station:not(:first-child)::before { left: 0; right: 50%; }
.ds-station:not(:last-child)::after { left: 50%; right: 0; }
.ds-station[data-seg-l="merged"]::before { background: #2da46e; }
.ds-station[data-seg-r="merged"]::after { background: #2da46e; }
.ds-station:hover { background: #1b2434; }
.ds-station:focus-visible { outline: 2px solid #46a0e6; outline-offset: 2px; }
.ds-station.ds-is-remaining { cursor: default; }
.ds-station.ds-is-remaining:hover { background: transparent; }
.ds-st-dot {
  width: 14px;
  height: 14px;
  border-radius: 50%;
  position: relative;
  z-index: 2;
  border: 2px solid #4c6282;
  background: #161e2b;
  transition: transform 150ms cubic-bezier(0.16, 1, 0.3, 1);
}
.ds-station:not(.ds-is-remaining):hover .ds-st-dot { transform: scale(1.16); }
.ds-st-dot-merged { background: #2da46e; border-color: #2da46e; }
.ds-st-dot-gate { width: 16px; height: 16px; margin: -1px 0; border-width: 3.5px; border-color: #e29524; }
.ds-st-dot-remaining { border-style: dashed; border-color: #8395ae; }
.ds-st-code {
  font: 700 11px/1.3 ui-monospace, "SF Mono", "Cascadia Mono", Menlo, Consolas, monospace;
  color: #a3b3c9;
}
.ds-station.ds-is-gate .ds-st-code { color: #f5bd63; }
.ds-st-state { font-size: 10.5px; color: #8395ae; }
.ds-station.ds-is-gate .ds-st-state { color: #d7b785; font-weight: 600; }

.ds-gate {
  display: grid;
  gap: 10px;
  padding: 14px 18px;
  border-radius: 4px;
  background: #1d170c;
  border: 1px solid #5e4419;
  font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
}
.ds-gate-top {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 18px;
  flex-wrap: wrap;
}
.ds-gate-lead {
  display: flex;
  align-items: flex-start;
  gap: 12px;
  min-width: 0;
  flex: 1 1 360px;
}
.ds-gate-icon {
  width: 28px;
  height: 28px;
  border-radius: 4px;
  flex: none;
  display: grid;
  place-items: center;
  background: #e29524;
  color: #170f00;
}
.ds-gate-copy { display: grid; gap: 4px; min-width: 0; }
.ds-gate-title { font-size: 15.5px; line-height: 1.35; font-weight: 700; color: #eef2f7; }
.ds-gate-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 4px 14px;
  align-items: baseline;
  font-size: 13px;
  color: #d7b785;
}
.ds-gate-kind {
  font: 700 11px/1.3 ui-monospace, "SF Mono", "Cascadia Mono", Menlo, Consolas, monospace;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: #f5bd63;
}
.ds-gate-link {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  color: #7cc4fa;
  text-decoration: none;
}
.ds-gate-link:hover, .ds-gate-link:focus-visible { text-decoration: underline; outline-color: #46a0e6; }
.ds-gate-acts { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
.ds-gate-cta {
  height: 32px;
  padding: 0 13px;
  border: 1px solid #e29524;
  border-radius: 4px;
  background: #e29524;
  color: #170f00;
  font: 700 13px/1.3 inherit;
  cursor: pointer;
  transition: background 140ms cubic-bezier(0.16, 1, 0.3, 1);
}
.ds-gate-cta:hover { background: #eba336; border-color: #eba336; }
.ds-gate-cta:focus-visible { outline: 2px solid #46a0e6; outline-offset: 2px; }
.ds-gate-quiet {
  height: 28px;
  padding: 0 9px;
  border: 1px solid transparent;
  border-radius: 4px;
  background: transparent;
  color: #a3b3c9;
  font: 600 12px/1.3 inherit;
  cursor: pointer;
}
.ds-gate-quiet:hover { color: #eef2f7; background: #1b2434; }
.ds-gate-quiet:focus-visible { outline: 2px solid #46a0e6; outline-offset: 2px; }
.ds-undo-track { height: 4px; border-radius: 2px; background: rgba(255, 255, 255, 0.12); overflow: hidden; }
.ds-undo-fill { height: 100%; width: 64%; background: #e29524; transition: width 100ms linear; }

.ds-nav-bar {
  display: flex;
  align-items: center;
  gap: 16px;
  min-height: 56px;
  padding: 0 20px;
  background: #131c2b;
  border-bottom: 1px solid #24334a;
  font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
}
.ds-brand-mark {
  width: 26px;
  height: 26px;
  border-radius: 3px;
  background: rgba(255, 255, 255, 0.08);
  border: 1px solid rgba(255, 255, 255, 0.22);
  color: #f4f7fb;
  display: grid;
  place-items: center;
}
.ds-nav-list { display: flex; align-items: stretch; gap: 2px; align-self: stretch; }
.ds-nav-tab {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 0 14px;
  border: 0;
  border-top: 3px solid transparent;
  border-bottom: 3px solid transparent;
  background: transparent;
  color: #9eb0c9;
  font-size: 13.5px;
  font-weight: 600;
  cursor: pointer;
  transition: color 150ms cubic-bezier(0.16, 1, 0.3, 1), border-color 150ms cubic-bezier(0.16, 1, 0.3, 1), background 150ms cubic-bezier(0.16, 1, 0.3, 1);
}
.ds-nav-tab:hover {
  color: #f4f7fb;
  background: rgba(255, 255, 255, 0.05);
}
.ds-nav-tab:focus-visible {
  outline: 2px solid #46a0e6;
  outline-offset: -2px;
}
.ds-nav-tab[aria-selected="true"] {
  color: #f4f7fb;
  border-bottom-color: #e29524;
}
.ds-nav-count {
  font-size: 11px;
  line-height: 16px;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  padding: 1px 7px;
  border-radius: 3px;
  background: rgba(255, 255, 255, 0.11);
  color: #dce5f2;
}
.ds-nav-count-warn {
  background: #e29524;
  color: #170f00;
}
